      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000);
  const vat1 = Math.round(10000 * 21 / 100); // 2100
  const vat2 = Math.round(10000 * 9 / 100); // 900
  const vat3 = 0;
  const expectedVat = vat1 + vat2 + vat3;
  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals vat is sum of line vats, not percent of total', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 20000, discountPercent: 0, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const vat1 = Math.round(10000 * 21 / 100);
  const vat2 = Math.round(20000 * 9 / 100);
  const expectedVat = vat1 + vat2;
  const wrongVat = Math.round((10000 + 20000) * 15 / 100); // wrong: would be avg VAT percent
  assert.equal(totals.vat, expectedVat);
  assert.notEqual(totals.vat, wrongVat);
});
